def count_beautiful_submatrices(n, m, matrix):
    count = 0

    # For each submatrix, check if it can be beautiful
    for r1 in range(n):
        for r2 in range(r1, n):
            for c1 in range(m):
                for c2 in range(c1, m):
                    # Get the submatrix
                    submatrix = matrix[r1:r2+1][c1:c2+1]

                    # Check if beautiful
                    rows_ok, cols_ok = check_beautiful(submatrix)
                    if rows_ok and cols_ok:
                        count += 1

    return count

def check_beautiful(submatrix):
    if not submatrix:
        return True, True

    h, w = len(submatrix), len(submatrix[0])

    # Check if each row can form a palindrome
    for row in submatrix:
        counts = Counter(row)
        if sum(1 for c in counts.values() if c % 2 == 1) > 1:
            return False, False

    # Check if columns can form palindromes
    # This requires that we can pair up characters symmetrically
    for col_idx in range(w):
        counts = Counter()
        for row_idx in range(h):
            counts[submatrix[row_idx][col_idx]] += 1

        # Check if column can form palindrome
        if sum(1 for c in counts.values() if c % 2 == 1) > 1:
            return False, False

    return True, True

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    matrix = [list(line) for line in lines[1:n+1]]

    return str(count_beautiful_submatrices(n, m, matrix))

