def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    def get_f(x, k):
        while x % k == 0:
            x //= k
        return x

    memo = {}

    def solve(numbers):
        state = tuple(sorted(numbers))
        if state in memo:
            return memo[state]

        if len(numbers) == 1:
            if numbers[0] == 1:
                return ['SUCCESS']
            else:
                return ['FAIL']

        result = None

        for i in range(len(numbers)):
            for j in range(i + 1, len(numbers)):
                x, y = numbers[i], numbers[j]
                new_val = get_f(x + y, k)
                new_nums = list(numbers)
                del new_nums[i]
                del new_nums[j - 1]
                new_nums.append(new_val)

                sub_result = solve(new_nums)
                if sub_result[0] == 'SUCCESS':
                    ops = [(x, y)]
                    if len(sub_result) > 1:
                        ops = [sub_result[1]] + ops
                    result = ops
                    break

            if result is not None:
                break

        memo[state] = result
        return result

    result = solve(a)
    if result is None or result[0] != 'SUCCESS':
        return "NO"

    operations = result[1] if len(result) > 1 else []
    output_lines = ["YES"]
    for x, y in reversed(operations):
        output_lines.append(f"{x} {y}")

    return "\n".join(output_lines) + "\n"
