def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return "NO"

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n)]

    for i in range(1, m + 1):
        parts = lines[i].split()
        a, b, c = int(parts[0]), int(parts[1]), int(parts[2])
        a -= 1
        b -= 1
        target = 1.0 if c == 1 else 2.0
        adj[a].append((b, target))
        adj[b].append((a, target))

    visited = [False] * n
    result = [0.0] * n

    for start_node in range(n):
        if visited[start_node]:
            continue

        # BFS to find all nodes in this connected component
        nodes = []
        queue = [start_node]
        visited[start_node] = True
        nodes.append(start_node)

        while queue:
            u = queue.pop(0)
            for v, _ in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    nodes.append(v)
                    queue.append(v)

        num_nodes = len(nodes)
        node_to_idx = {node: i for i, node in enumerate(nodes)}

        # Filter edges that belong to this component
        comp_edges = []
        for u, v, target in (e for lst in [adj[n] for n in nodes] for e in lst):
            if u in node_to_idx and v in node_to_idx:
                comp_edges.append((u, v, target))

        # Build constraint matrix: each edge gives x[u] + x[v] = target
        num_rows = len(comp_edges)
        matrix = [[0.0] * (num_nodes + 1) for _ in range(num_rows)]

        for row, (u, v, target) in enumerate(comp_edges):
            matrix[row][node_to_idx[u]] = 1.0
            matrix[row][node_to_idx[v]] = 1.0
            matrix[row][num_nodes] = target

        # Gaussian elimination (forward phase)
        col = 0
        row = 0
        for col in range(min(num_nodes, num_rows)):
            # Find pivot with largest absolute value
            max_row = row
            for r in range(row + 1, min(num_nodes, num_rows)):
                if abs(matrix[r][col]) > abs(matrix[max_row][col]):
                    max_row = r

            if abs(matrix[max_row][col]) < 1e-9:
                continue

            if max_row != row:
                matrix[row], matrix[max_row] = matrix[max_row], matrix[row]

            for r in range(row + 1, min(num_nodes, num_rows)):
                if abs(matrix[r][col]) > 1e-9:
                    factor = matrix[r][col] / matrix[row][col]
                    for c in range(col, num_nodes + 1):
                        matrix[r][c] -= factor * matrix[row][c]
            row += 1

        # Back substitution
        try:
            x = [0.0] * num_nodes
            for i in range(min(num_nodes, num_rows) - 1, -1, -1):
                if abs(matrix[i][i]) < 1e-9:
                    x[i] = 0.0
                else:
                    val = matrix[i][num_nodes]
                    for j in range(i + 1, num_nodes):
                        val -= matrix[i][j] * x[j]
                    x[i] = val / matrix[i][i]
        except ZeroDivisionError:
            return "NO"

        for i, node in enumerate(nodes):
            result[node] = x[i]

    # Format output
    formatted = []
    for v in result:
        if v == int(v):
            formatted.append(f"{v}")
        else:
            formatted.append(f"{v:.6f}")

    return "YES\n" + " ".join(formatted) + " "
