Looking at this problem, I need to:

1. Count ways to form a bouquet with exactly N flowers (order matters)
2. Count ways to form a basket with any number of boxes (order matters)
3. Total petals = Total chocolates

This is essentially finding the sum over all possible sums S of:
(coefficient of x^S in (∑x^pi)^N) × (coefficient of x^S in 1/(1-∑x^ci))

For large N (up to 10^18), I'll use matrix exponentiation for efficiency.

```python
def solution(s):
    lines = s.strip().split('\n')
    if not lines:
        return "0\n"

    first_line = lines[0].split()
    F = int(first_line[0])
    B = int(first_line[1])
    N = int(first_line[2])

    petals = list(map(int, lines[1].split()))
    chocolates = list(map(int, lines[2].split()))

    MOD = 1000000007

    if N == 0:
        # 0 flowers: only sum 0 possible
        # 0 chocolates: only way is empty basket (1 way)
        return "1\n"

    max_petal = max(petals) if petals else 1
    min_petal = min(petals) if petals else 1

    # For large N, we need to compute (sum x^petal)^N efficiently
    # Use a reasonable bound based on chocolate sizes
    max_chocolate = max(chocolates) if chocolates else 1
    limit = max(250, max_chocolate)

    # Determine the range of possible sums where both flowers and boxes can match
    # For boxes: any number of boxes, so can match up to some max
    # For flowers: N flowers with min_petal each

    # We'll compute the polynomial for flowers and boxes up to a reasonable limit
    # The key is that für very large N=max_sum can be huge, but we can use matrix exponentiation
    # and focus on sums that are reachable by both

    def mat_mult(A, B):
        n = len(A)
        m = len(B)
        p = len(B[0])
        result = [[0] * p for _ in range(n)]
        for i in range(n):
            for k in range(m):
                if A[i][k] == 0:
                    continue
                for j in range(p):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % MOD
        return result

    def mat_pow(A, p):
        n = len(A)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1
        base = A
        while p > 0:
            if p & 1:
                result = mat_mult(result, base)
            base = mat_mult(base, base)
            p >>= 1
        return result

    # Build the transition matrix for flowers
    # Size based on limit value
    limit_val = max_chocolate + 100 if max_chocolate < 1000 else max_chocolate + 100
    limit_val = min(limit_val, 300)

    petal_matrix = [[0] * (limit_val + 1) for _ in range(limit_val + 1)]
    for p in petals:
        if p <= limit_val:
            for i in range(limit_val + 1 - p):
                petal_matrix[i][i + p] = (petal_matrix[i][i + p] + 1) % MOD

    # Apply matrix exponentiation for N flowers
    flower_matrix = mat_pow(petal_matrix, N)

    # Extract the polynomial from the matrix
    # flower_poly[s] = flower_matrix[0][s] (starting from 0)
    max_s = 250
    flower_poly = [flower_matrix[0][i] for i in range(max_s + 1)]

    # Compute the box polynomial using DP
    # This represents 1/(1-∑x^ci)
    box_poly = [0] * (max_s + 2)
    box_poly[0] = 1

    for s in range(1, max_s + 1):
        for c in chocolates:
            if s >= c:
                box_poly[s] = (box_poly[s] + box_poly[s - c]) % MOD

    # Compute the answer: sum of product of matching coefficients
    ans = 0
    min_len = min(len(flower_poly), len(box_poly))
    for i in range(min_len):
        ans = (ans + flower_poly[i] * box_poly[i]) % MOD

    return f"{ans}\n"
