def multiply_poly(a, b):
    """Multiply two dense polynomials mod MOD"""
    res = [0] * (len(a) + len(b) - 1)
    for i in range(len(a)):
        if a[i] == 0:
            continue
        for j in range(len(b)):
            if b[j] == 0:
                continue
            res[i + j] = (res[i + j] + a[i] * b[j]) % MOD
    return res

def power_poly(p, n):
    """Compute p^n using binary exponentiation for polynomials"""
    if n == 0:
        return [1]
    result = [1]
    base = p[:]
    while n > 0:
        if n & 1:
            result = multiply_poly(result, base)
        base = multiply_poly(base, base)
        n >>= 1
    return result

def integrate_poly(coeffs):
    """Integrate polynomial sum(a_i * x^i) from 0 to 1, giving sum(a_i / (i+1))"""
    res = 0
    for i, a in enumerate(coeffs):
        res = (res + a * inv[i + 1]) % MOD
    return res

