```python
import math

def solution(input_str):
    # Helper to get divisors > 1
    def get_divisors(n):
        divs = set()
        for i in range(2, int(math.isqrt(n)) + 1):
            if n % i == 0:
                divs.add(i)
                if i != n // i:
                    divs.add(n // i)
        return sorted(list(divs))

    # Helper to get prime factors
    def get_prime_factors(x):
        factors = []
        d = 2
        while d * d <= x:
            if x % d == 0:
                factors.append(d)
                while x % d == 0:
                    x //= d
            d += 1
        if x > 1:
            factors.append(x)
        return factors if factors else [x]

    # Parse input and process test cases
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    t = int(lines[0])
    results = []

    for i in range(1, t + 1):
        if i >= len(lines):
            break
        n = int(lines[i])

        divs = get_divisors(n)
        if not divs:
            results.append("")
            results.append("0")
            continue

        # Group divisors by their prime factors
        prime_to_divs = {}
        for d in divs:
            primes = get_prime_factors(d)
            for p in primes:
                if p not in prime_to_divs:
                    prime_to_divs[p] = []
                if d not in prime_to_divs[p]:
                    prime_to_divs[p].append(d)

        # Find the prime with most divisors (best for grouping)
        main_prime = max(prime_to_divs.keys(), key=lambda p: len(prime_to_divs[p]))

        # Get divisors divisible by main_prime
        multiples = sorted([d for d in divs if d % main_prime == 0], reverse=True)

        # Build order: multiples of main_prime first, then fill the gap
        if multiples:
            order = [multiples[0]]
            to_add = set([d for d in multiples[1:]])
            other_divs = set(d for d in divs if d not in to_add)

            # Add remaining divisors greedily by prime compatibility
            for other in other_divs:
                other_primes = get_prime_factors(other)
                compatible = False
                for p in other_primes:
                    if p in to_add:
                        compatible = True
                        break
                if not compatible:
                    order.append(other)
                    to_add.add(other)

            order.extend(sorted(to_add, reverse=True))
        else:
            order = divs

        # Verify moves needed (count coprime adjacent pairs)
        moves = 0
        n_len = len(order)
        for i in range(n_len):
            a = order[i]
            b = order[(i + 1) % n_len]
            if math.gcd(a, b) == 1:
                moves += 1

        results.append(" ".join(map(str, order)))
        results.append(str(moves))

    return '\n'.join(results)


