import bisect
import sys

sys.setrecursionlimit(300000)

class MergeSortTree:
    def __init__(self, arr):
        self.n = len(arr)
        self.tree = [[] for _ in range(4 * self.n)]
        self.arr = arr
        self._build(1, 0, self.n - 1)

    def _build(self, node, start, end):
        if start == end:
            self.tree[node] = [self.arr[start]]
        else:
            mid = (start + end) // 2
            self._build(2 * node, start, mid)
            self._build(2 * node + 1, mid + 1, end)
            self.tree[node] = sorted(self.tree[2 * node] + self.tree[2 * node + 1])

    def update(self, idx, new_val):
        self._update(1, 0, self.n - 1, idx, new_val)
        self.arr[idx] = new_val

    def _update(self, node, start, end, idx, new_val):
        if start == end:
            self.tree[node] = [new_val]
            return

        mid = (start + end) // 2
        if idx <= mid:
            self._update(2 * node, start, mid, idx, new_val)
        else:
            self._update(2 * node + 1, mid + 1, end, idx, new_val)
        self.tree[node] = sorted(self.tree[2 * node] + self.tree[2 * node + 1])

    def count_in_range(self, l, r, val_min, val_max):
        if l > r or val_min > val_max:
            return 0
        return self._count(1, 0, self.n - 1, l, r, val_min, val_max)

    def _count(self, node, start, end, l, r, val_min, val_max):
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            sorted_arr = self.tree[node]
            left_idx = bisect.bisect_left(sorted_arr, val_min)
            right_idx = bisect.bisect_right(sorted_arr, val_max)
            return right_idx - left_idx

        mid = (start + end) // 2
        return self._count(2 * node, start, mid, l, r, val_min, val_max) + \
               self._count(2 * node + 1, mid + 1, end, l, r, val_min, val_max)


def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n, q = map(int, lines[0].split())
    queries = []
    for i in range(1, len(lines)):
        if not lines[i]:
            continue
        tu = list(map(int, lines[i].split()))
        queries.append(tu)

    permutation = list(range(1, n + 1))

    mst = MergeSortTree(permutation)
    inversions = 0

    output = []
    for l, r in queries:
        if l == r:
            output.append(str(inversions))
            continue

        pos1 = l - 1
        pos2 = r - 1
        if pos1 > pos2:
            pos1, pos2 = pos2, pos1

        val_l = permutation[pos1]
        val_r = permutation[pos2]

        if val_l > val_r:
            change = -1
        else:
            change = 1
            count_between = mst.count_in_range(pos1 + 1, pos2 - 1, val_r, val_l)
            change -= count_between

        if change != 0:
            output.append(str(inversions + change))
            inversions += change
        else:
            output.append(str(inversions))

    return '\n'.join(output)
