MOD = 10**9 + 7

def solution(input_str):
    s = input_str.strip()
    n = len(s)
    pos = [0]

    def long_to_mod(s_val):
        """Convert long string representation to integer modulo 10^9+7"""
        result = 0
        for c in s_val:
            result = (result * 10 + int(c)) % MOD
        return result

    def parse_number():
        """Parse a number from the string, returns integer value"""
        start = pos[0]
        while pos[0] < n and s[pos[0]].isdigit():
            pos[0] += 1
        return int(s[start:pos[0]])

    def parse_expr():
        """Parse expression (sequence of terms separated by +)"""
        result_parts = []
        while pos[0] < n:
            part = parse_term()
            result_parts.append(part)
            if pos[0] < n and s[pos[0]] == '+':
                pos[0] += 1
                continue
            break
        return "".join(result_parts)

    def parse_term():
        """Parse a single term (number, range, or repetition)"""
        nonlocal pos
        num = parse_number()

        # Check if it's a range (<number>-<number>)
        if pos[0] < n and s[pos[0]] == '-':
            pos[0] += 1
            end_num = parse_number()
            # Build the range string by concatenating all numbers
            result_chars = []
            for i in range(num, end_num + 1):
                result_chars.append(str(i))
            return "".join(result_chars)

        # Check if it's a repetition (<number>(<expression>))
        elif pos[0] < n and s[pos[0]] == '(':
            pos[0] += 1  # Skip '('
            inner_expr, pos[0] = parse_expr()
            if pos[0] < n and s[pos[0]] == ')':
                pos[0] += 1  # Skip ')'
            # Return the expression repeated 'num' times
            return inner_expr * num

        # Otherwise it's just a number
        else:
            return str(num)

    result = parse_expr()
    return str(long_to_mod(result))


